export function combineAccessRoute(vehicle,walk){return combineRouteLegs([vehicle,walk])}
export function combineRouteLegs(input){
 if(!Array.isArray(input)||input.length<2||input.length>3||input.some(l=>l.legs))throw Error('Invalid access route');const legs=input.map(validateRoute),vehicles=legs.filter(l=>['car','bus','motor','perahu','boat','boat_vip'].includes(l.mode));
 if(vehicles.length!==1||legs.some(l=>!['walk','car','bus','motor','perahu','boat','boat_vip'].includes(l.mode))||legs.slice(1).some((l,i)=>distanceMetres(legs[i].path.at(-1),l.path[0])>25))throw Error('Invalid walking transfer');
 const distance=legs.reduce((a,l)=>a+l.distanceMetres,0),duration=legs.reduce((a,l)=>a+l.durationSeconds,0);if(distance>200000||duration>86400)throw Error('Access route too long');
 const weights=leg=>{const sum=leg.segmentSeconds.reduce((a,b)=>a+b,0),moving=leg.durationSeconds-(leg.mode==='bus'?120:0);return leg.segmentSeconds.map(s=>s/sum*moving)};
 return {mode:vehicles[0].mode,sourceSeconds:legs.reduce((a,l)=>a+l.sourceSeconds,0),path:legs.flatMap((l,i)=>i?l.path.slice(1):l.path),segmentSeconds:legs.flatMap(weights),durationSeconds:duration,distanceMetres:distance,startAccessMetres:legs[0].startAccessMetres,endAccessMetres:legs.at(-1).endAccessMetres,provider:TRANSPORTS[vehicles[0].mode].domain==='sea'?'GEOPARK-MIXED':'OSRM',legs};
}
export function routeModeAt(route,index){let offset=0;for(const leg of route.legs||[route]){offset+=leg.path.length-1;if(index<offset)return leg.mode||'car'}return route.legs?.at(-1).mode||route.mode||'car'}
function journeyAtLegs(j,now){
 const durations=j.route.legs.map(l=>Math.ceil(l.durationSeconds/TIME_RATIO*1000)),gameMs=durations.reduce((a,b)=>a+b,0),elapsed=Math.max(0,(j.pausedAt??now)-j.startedAt-j.pausedMs);let before=0,offset=0;
 for(let i=0;i<j.route.legs.length;i++){const leg=j.route.legs[i];if(elapsed<before+durations[i]||i===j.route.legs.length-1){const state=journeyAt({route:leg,startedAt:now-Math.max(0,elapsed-before),pausedMs:0,pausedAt:null},now);return {...state,legIndex:i,index:offset+state.index,gameMs,fraction:Math.min(1,elapsed/gameMs),remainingMs:Math.max(0,gameMs-elapsed),arrived:elapsed>=gameMs}}before+=durations[i];offset+=leg.path.length-1}
}
export function normaliseRoadResponse(data,mode='car'){if(data?.code!=='Ok'||!data.routes?.[0]||data.waypoints?.length!==2)throw Error('No route');const r=data.routes[0],seconds=r.legs?.flatMap(l=>l.annotation?.duration||[])||[];if(r.geometry?.type!=='LineString')throw Error('Invalid geometry');return validateRoute({path:r.geometry.coordinates.map(p=>[p[1],p[0]]),segmentSeconds:seconds,mode,sourceSeconds:r.duration,durationSeconds:modeDuration(mode,r.distance,r.duration),distanceMetres:r.distance,startAccessMetres:data.waypoints[0].distance,endAccessMetres:data.waypoints[1].distance});}
export function validateJourney(j,sites,now=Date.now()){if(!j||j.version!==1||!Number.isSafeInteger(j.startedAt)||!sites.some(s=>s.id===j.fromId)||!sites.some(s=>s.id===j.toId)||!finite(j.startedAt,1,now+60000)||!finite(j.pausedMs,0,now-j.startedAt+60000)||(j.pausedAt!==null&&!finite(j.pausedAt,j.startedAt,now+60000)))throw Error('Invalid journey');const from=sites.find(s=>s.id===j.fromId),to=sites.find(s=>s.id===j.toId);const route=validateRoute(j.route);if(!travelOptions(from,to).includes(route.mode))throw Error('Unsupported transport for access');if(distanceMetres(route.path[0],[from.lat,from.lng])>1500||distanceMetres(route.path.at(-1),[to.lat,to.lng])>1500)throw Error('Wrong route endpoints');return {version:1,fromId:j.fromId,toId:j.toId,route,startedAt:j.startedAt,pausedMs:j.pausedMs,pausedAt:j.pausedAt};}
export function journeyAt(j,now=Date.now()){if(j.route.legs)return journeyAtLegs(j,now);const gameMs=Math.ceil(j.route.durationSeconds/TIME_RATIO*1000),elapsedMs=Math.max(0,(j.pausedAt??now)-j.startedAt-j.pausedMs),fraction=Math.min(1,elapsedMs/gameMs),waitMs=j.route.mode==='bus'?120000/TIME_RATIO:0,movingFraction=Math.max(0,Math.min(1,(elapsedMs-waitMs)/Math.max(1,gameMs-waitMs))),sum=j.route.segmentSeconds.reduce((a,b)=>a+b,0),target=movingFraction*sum;if(elapsedMs<waitMs)return {mode:j.route.mode||'car',fraction,position:[...j.route.path[0]],index:0,waiting:true,remainingMs:Math.max(0,gameMs-elapsedMs),gameMs,arrived:false};let spent=0,index=0;while(index<j.route.segmentSeconds.length-1&&spent+j.route.segmentSeconds[index]<=target){spent+=j.route.segmentSeconds[index];index++}const duration=j.route.segmentSeconds[index],part=duration>0?Math.min(1,Math.max(0,(target-spent)/duration)):1,a=j.route.path[index],b=j.route.path[index+1];const position=fraction>=1?[...j.route.path.at(-1)]:[a[0]+(b[0]-a[0])*part,a[1]+(b[1]-a[1])*part];return {mode:routeModeAt(j.route,index),fraction,position,index,waiting:elapsedMs<waitMs,remainingMs:Math.max(0,gameMs-elapsedMs),gameMs,arrived:fraction>=1};}
export function formatClock(ms){const s=Math.max(0,Math.ceil(ms/1000)),h=Math.floor(s/3600),m=Math.floor(s%3600/60),sec=s%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`:`${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`;}
